CREATE TABLE IF NOT EXISTS term_offerings (id VARCHAR(8) PRIMARY KEY,course_id VARCHAR(20) NOT NULL,start_date VARCHAR(10) NOT NULL,created_at VARCHAR(30) NOT NULL,discussion_locked INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,UNIQUE(course_id,start_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_enrollments (id VARCHAR(32) PRIMARY KEY,offering_id VARCHAR(8) NOT NULL,user_id VARCHAR(32) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'enrolled',consent_version INTEGER NOT NULL,enrolled_at VARCHAR(30) NOT NULL,last_activity_at VARCHAR(30) NULL,ended_at VARCHAR(30) NULL,UNIQUE(offering_id,user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(offering_id) REFERENCES term_offerings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_professors (offering_id VARCHAR(8) NOT NULL,user_id VARCHAR(32) NOT NULL,assigned_at VARCHAR(30) NOT NULL,PRIMARY KEY(offering_id,user_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(offering_id) REFERENCES term_offerings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_papers (id VARCHAR(32) PRIMARY KEY,enrollment_id VARCHAR(32) NOT NULL,week_index INTEGER NOT NULL,task_kind VARCHAR(12) NOT NULL,revision INTEGER NOT NULL,document_json MEDIUMTEXT NOT NULL,word_count INTEGER NOT NULL,status VARCHAR(16) NOT NULL,originality INTEGER NOT NULL DEFAULT 0,peer_consent INTEGER NOT NULL DEFAULT 0,consent_version INTEGER NOT NULL DEFAULT 0,teacher_status VARCHAR(24) NOT NULL DEFAULT 'pending',feedback TEXT NULL,rubric_json TEXT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at VARCHAR(30) NOT NULL,submitted_at VARCHAR(30) NULL,reviewed_at VARCHAR(30) NULL,UNIQUE(enrollment_id,week_index,task_kind,revision),FOREIGN KEY(enrollment_id) REFERENCES term_enrollments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_batches (id VARCHAR(32) PRIMARY KEY,offering_id VARCHAR(8) NOT NULL,week_index INTEGER NOT NULL,task_kind VARCHAR(12) NOT NULL,cutoff_at VARCHAR(30) NOT NULL,processed_at VARCHAR(30) NOT NULL,papers_count INTEGER NOT NULL,teacher_fallback INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(offering_id) REFERENCES term_offerings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_peer_routes (paper_id VARCHAR(32) PRIMARY KEY,batch_id VARCHAR(32) NULL,outcome VARCHAR(24) NOT NULL,reason TEXT NOT NULL,decided_by VARCHAR(32) NULL,decided_at VARCHAR(30) NOT NULL,FOREIGN KEY(paper_id) REFERENCES term_papers(id),FOREIGN KEY(batch_id) REFERENCES term_batches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_peer_assignments (id VARCHAR(32) PRIMARY KEY,batch_id VARCHAR(32) NOT NULL,paper_id VARCHAR(32) NOT NULL,reviewer_enrollment_id VARCHAR(32) NOT NULL,rubric_json TEXT NULL,feedback TEXT NULL,score INTEGER NULL,submitted_at VARCHAR(30) NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(batch_id,reviewer_enrollment_id),FOREIGN KEY(batch_id) REFERENCES term_batches(id),FOREIGN KEY(paper_id) REFERENCES term_papers(id),FOREIGN KEY(reviewer_enrollment_id) REFERENCES term_enrollments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_peer_adjustments (id VARCHAR(32) PRIMARY KEY,assignment_id VARCHAR(32) NOT NULL,teacher_id VARCHAR(32) NOT NULL,revision INTEGER NOT NULL,rubric_json TEXT NOT NULL,reason TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,UNIQUE(assignment_id,revision),FOREIGN KEY(assignment_id) REFERENCES term_peer_assignments(id),FOREIGN KEY(teacher_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_discussions (id VARCHAR(32) PRIMARY KEY,offering_id VARCHAR(8) NOT NULL,week_index INTEGER NOT NULL,user_id VARCHAR(32) NOT NULL,body TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'pending',request_id VARCHAR(32) NOT NULL,created_at VARCHAR(30) NOT NULL,UNIQUE(user_id,request_id),FOREIGN KEY(offering_id) REFERENCES term_offerings(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_certificates (id VARCHAR(32) PRIMARY KEY,enrollment_id VARCHAR(32) NOT NULL UNIQUE,user_id VARCHAR(32) NOT NULL,certificate_number VARCHAR(40) NOT NULL UNIQUE,student_number VARCHAR(40) NOT NULL,student_name VARCHAR(120) NOT NULL,course_title VARCHAR(160) NOT NULL,attempt_id VARCHAR(32) NOT NULL,score INTEGER NOT NULL,maximum INTEGER NOT NULL,signatories_json TEXT NOT NULL,issued_at VARCHAR(30) NOT NULL,FOREIGN KEY(enrollment_id) REFERENCES term_enrollments(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_extensions (enrollment_id VARCHAR(32) NOT NULL,week_index INTEGER NOT NULL,until_at VARCHAR(30) NOT NULL,reason TEXT NOT NULL,teacher_id VARCHAR(32) NOT NULL,created_at VARCHAR(30) NOT NULL,PRIMARY KEY(enrollment_id,week_index),FOREIGN KEY(enrollment_id) REFERENCES term_enrollments(id),FOREIGN KEY(teacher_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_practice (enrollment_id VARCHAR(32) NOT NULL,week_index INTEGER NOT NULL,notes TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at VARCHAR(30) NOT NULL,PRIMARY KEY(enrollment_id,week_index),FOREIGN KEY(enrollment_id) REFERENCES term_enrollments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_legacy_access (user_id VARCHAR(32) NOT NULL,course_id VARCHAR(20) NOT NULL,recorded_at VARCHAR(30) NOT NULL,PRIMARY KEY(user_id,course_id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS term_scheduler (id INTEGER PRIMARY KEY,last_run_at VARCHAR(30) NOT NULL,last_cron_at VARCHAR(30) NULL,scan_offset INTEGER NOT NULL DEFAULT 0,batches_processed INTEGER NOT NULL DEFAULT 0,inactive_unenrolled INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
